package main

import "net"

// ✅ NEW: A goroutine per connection, but the goroutines are CHEAP:
// ~2KB stacks that grow, and while a connection waits for data the
// goroutine parks on the NETPOLLER (epoll/kqueue), freeing the OS
// thread entirely. One thread can serve thousands of connections.
func main() {
	ln, err := net.Listen("tcp", ":8080")
	if err != nil {
		panic(err)
	}
	for {
		conn, err := ln.Accept()
		if err != nil {
			continue
		}
		go handle(conn) // ✅ NEW: cheap goroutine, not a thread
	}
}

func handle(c net.Conn) {
	defer c.Close()
	buf := make([]byte, 4096)
	for {
		n, err := c.Read(buf) // ✅ NEW: parks on the netpoller until data
		if err != nil {
			return
		}
		// process n bytes...
	}
}

// Internally: c.Read -> pollDesc -> epoll_ctl + gopark. The OS thread
// runs other goroutines while this one waits.
